design.css:
/* Iris — the Senshi look (docs/theme-references/senshi.md; numbers in tmp/parity/iris/measure.md).
   #0F0F11 page, system sans, purple-600 actions, purple-400 accents, #18181B surfaces with white/5 hairlines. */

/* ── Header: 80px (the 32px titlebar band + a 48px row), clear at the top of a page; once scrolled
   #0F0F11 at 80% with a 24px blur, a white/5 hairline and shadow-sm (300ms ease-out, as the site). ── */
@media (min-width: 641px) { :scope { --theme-top-row: 48px; } }
[data-slot="nav.top"] { padding-left: 24px !important; padding-right: 32px !important; background: transparent !important; border: 0 !important; border-bottom: 1px solid transparent !important; box-shadow: none !important; transition: background-color 300ms ease-out, border-color 300ms ease-out, box-shadow 300ms ease-out; }
[data-slot="nav.top"][data-scrolled] { background: rgba(15, 15, 17, 0.8) !important; backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px); border-bottom-color: rgba(255, 255, 255, 0.05) !important; box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05) !important; }
/* Search: right after the brand (16px gap + 32px margin), flex-1 up to 576px, 40px tall, #18181B, r12. */
[data-slot="nav.top"] > div:has([data-part="search.field"]) { order: 2; flex: 1 1 auto; max-width: 576px; margin: 0 44px; padding: 0 !important; }
[data-slot="nav.top"] > div:has([data-part="search.field"]) form { max-width: none !important; }
[data-slot="nav.top"] > div:has([data-part="search.field"]) form > svg { left: 16px !important; width: 16px; height: 16px; color: #737373 !important; }
[data-slot="nav.top"] [data-part="search.field"] { height: 40px !important; padding: 10px 12px 10px 44px !important; border: 1px solid rgba(255, 255, 255, 0.05) !important; border-radius: 12px !important; background: #18181b !important; font-size: 14px !important; font-weight: 500; color: #fff; }
[data-slot="nav.top"] [data-part="search.field"]::placeholder { color: #737373; }
[data-slot="nav.top"] [data-part="search.field"]:hover { border-color: rgba(255, 255, 255, 0.1) !important; }
[data-slot="nav.top"] [data-part="search.field"]:focus { border-color: rgba(168, 85, 247, 0.5) !important; }
/* Links: 14/700 neutral-400, 8px 12px, r8, 16px purple-400/70 icons, 4px apart. */
[data-slot="nav.top"] > [data-part="nav.item"] { order: 3; height: 36px !important; padding: 8px 12px !important; gap: 8px !important; border-radius: 8px !important; color: #a3a3a3 !important; font-size: 14px !important; font-weight: 700 !important; line-height: 20px; background: transparent !important; }
[data-slot="nav.top"] > [data-part="nav.item"]:hover, [data-slot="nav.top"] > [data-part="nav.item"][data-active] { color: #fff !important; }
[data-slot="nav.top"] > [data-part="nav.item"]:hover { background: rgba(255, 255, 255, 0.05) !important; }
[data-slot="nav.top"] [data-part="nav.item.icon"], [data-slot="nav.top"] [data-part="nav.item.icon"] svg { width: 16px !important; height: 16px !important; color: rgba(192, 132, 252, 0.7) !important; }
/* Right cluster: 40px r12 neutral-400 icon buttons, 8px apart, 24px after the links. */
[data-slot="nav.top"] > [data-part="nav.action"] { order: 4; width: 40px; height: 40px; border-radius: 12px !important; color: #a3a3a3 !important; margin-left: 4px; }
[data-slot="nav.top"] > div:has([data-part="search.field"]) + [data-part="nav.action"] { margin-left: 20px; }
[data-slot="nav.top"] > [data-part="nav.action"]:hover { color: #fff !important; background: rgba(255, 255, 255, 0.05) !important; }

/* Live results: the field's width, #18181B, 16px corners, 72px rows with a 40×56 poster, purple-400 title. */
[data-part="search.suggestions"] { margin-top: 17px !important; padding: 8px !important; border: 1px solid rgba(255, 255, 255, 0.1) !important; border-radius: 16px !important; background: #18181b !important; box-shadow: none !important; }
[data-part="search.suggestion"] { min-height: 72px; padding: 8px !important; border-radius: 12px !important; gap: 12px !important; }
[data-part="search.suggestion"]:hover, [data-part="search.suggestion"][data-active] { background: rgba(255, 255, 255, 0.05) !important; }
[data-part="search.suggestion.poster"] { width: 40px !important; height: 56px !important; border-radius: 8px !important; }
[data-part="search.suggestion.title"] { color: #c084fc; font-size: 14px !important; font-weight: 600 !important; }
[data-part="search.suggestion.meta"] { margin-top: 2px; font-size: 11px !important; color: #a1a1aa !important; }
[data-part="search.suggestion.all"] { display: none !important; }

/* ── Hero: 75vh under the bar, art with one left-to-right neutral-950 fade, copy bottom-left. ── */
@media (min-width: 641px) { [data-slot="home.hero"] { margin-bottom: 48px !important; } }
[data-part="iris.hero"]::after { content: ""; position: absolute; inset: 0; z-index: 1; background-image: linear-gradient(to right, rgb(10, 10, 10), rgba(10, 10, 10, 0.7), rgba(0, 0, 0, 0)); pointer-events: none; }
[data-part="iris.hero"] > :not(:first-child) { z-index: 2; }
[data-part="iris.info"] { width: 672px !important; max-width: 100%; padding-bottom: 112px !important; }
[data-part="iris.title"] { line-height: 48px !important; margin-bottom: 8px; filter: drop-shadow(0 10px 8px rgba(0, 0, 0, 0.04)) drop-shadow(0 4px 3px rgba(0, 0, 0, 0.1)); }
[data-part="iris.synopsis"] { line-height: 22.75px !important; padding-right: 8px; margin-bottom: 16px; }
[data-part="iris.play"] { padding: 12px 24px !important; gap: 8px !important; line-height: 24px; }
[data-part="iris.play"]:hover { background: #7e22ce !important; }
[data-part="iris.play"] svg, [data-part="iris.save"] svg, [data-part="iris.prev"] svg, [data-part="iris.next"] svg { display: none !important; }
[data-part="iris.play"]::before, [data-part="iris.save"]::before, [data-part="iris.prev"]::before, [data-part="iris.next"]::before { content: ""; flex: none; background: currentColor; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-size: contain; mask-size: contain; -webkit-mask-position: center; mask-position: center; }
[data-part="iris.play"]::before { width: 12px; height: 16px; -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20384%20512%27%3E%3Cpath%20d%3D%27M73%2039c-14.8-9.1-33.4-9.4-48.5-.9S0%2062.6%200%2080L0%20432c0%2017.4%209.4%2033.4%2024.5%2041.9s33.7%208.1%2048.5-.9L361%20297c14.3-8.7%2023-24.2%2023-41s-8.7-32.2-23-41L73%2039z%27%2F%3E%3C%2Fsvg%3E"); mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20384%20512%27%3E%3Cpath%20d%3D%27M73%2039c-14.8-9.1-33.4-9.4-48.5-.9S0%2062.6%200%2080L0%20432c0%2017.4%209.4%2033.4%2024.5%2041.9s33.7%208.1%2048.5-.9L361%20297c14.3-8.7%2023-24.2%2023-41s-8.7-32.2-23-41L73%2039z%27%2F%3E%3C%2Fsvg%3E"); }
[data-part="iris.save"] { width: 43px; padding: 14px !important; justify-content: center; background: rgba(255, 255, 255, 0.1) !important; }
[data-part="iris.save"]:hover { background: rgba(255, 255, 255, 0.2) !important; }
[data-part="iris.save"]::before { width: 15px; height: 20px; -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20384%20512%27%3E%3Cpath%20d%3D%27M0%2048V487.7C0%20501.1%2010.9%20512%2024.3%20512c5%200%209.9-1.5%2014-4.4L192%20400%20345.7%20507.6c4.1%202.9%209%204.4%2014%204.4c13.4%200%2024.3-10.9%2024.3-24.3V48c0-26.5-21.5-48-48-48H48C21.5%200%200%2021.5%200%2048z%27%2F%3E%3C%2Fsvg%3E"); mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20384%20512%27%3E%3Cpath%20d%3D%27M0%2048V487.7C0%20501.1%2010.9%20512%2024.3%20512c5%200%209.9-1.5%2014-4.4L192%20400%20345.7%20507.6c4.1%202.9%209%204.4%2014%204.4c13.4%200%2024.3-10.9%2024.3-24.3V48c0-26.5-21.5-48-48-48H48C21.5%200%200%2021.5%200%2048z%27%2F%3E%3C%2Fsvg%3E"); }
[data-part="iris.prev"], [data-part="iris.next"] { width: 34px; height: 48px; padding: 12px !important; justify-content: center; border-radius: 9999px !important; background: rgba(0, 0, 0, 0.5) !important; }
[data-part="iris.prev"]:hover, [data-part="iris.next"]:hover { background: rgba(0, 0, 0, 0.7) !important; }
[data-part="iris.prev"]::before, [data-part="iris.next"]::before { width: 10px; height: 16px; -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20320%20512%27%3E%3Cpath%20d%3D%27M9.4%20233.4c-12.5%2012.5-12.5%2032.8%200%2045.3l192%20192c12.5%2012.5%2032.8%2012.5%2045.3%200s12.5-32.8%200-45.3L77.3%20256%20246.6%2086.6c12.5-12.5%2012.5-32.8%200-45.3s-32.8-12.5-45.3%200l-192%20192z%27%2F%3E%3C%2Fsvg%3E"); mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20320%20512%27%3E%3Cpath%20d%3D%27M9.4%20233.4c-12.5%2012.5-12.5%2032.8%200%2045.3l192%20192c12.5%2012.5%2032.8%2012.5%2045.3%200s12.5-32.8%200-45.3L77.3%20256%20246.6%2086.6c12.5-12.5%2012.5-32.8%200-45.3s-32.8-12.5-45.3%200l-192%20192z%27%2F%3E%3C%2Fsvg%3E"); }
[data-part="iris.next"]::before { transform: scaleX(-1); }
[data-part="iris.count"] > * { line-height: 24px; }

/* ── Rows: 48px apart, heading 24px above a track that starts 4px in and clips at the column. ── */
[data-slot="home.main"] [data-slot="row"] { margin-bottom: 48px !important; }
[data-part="row.header"] { margin-bottom: 24px !important; align-items: center !important; }
[data-slot="home.main"] [data-part="row.track"] { margin: 0 32px; padding-left: 4px !important; padding-right: 4px !important; padding-bottom: 24px !important; }
[data-part="row.title"] { position: relative; display: inline-flex !important; align-items: center; gap: 12px; overflow: visible !important; font-size: 30px !important; line-height: 36px; font-weight: 700 !important; color: #c084fc; }
[data-part="row.title"]::before { content: ""; flex: none; background: currentColor; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-size: contain; mask-size: contain; -webkit-mask-position: center; mask-position: center; }
[data-part="row.more"] { opacity: 1 !important; font-size: 0 !important; }
[data-part="row.more"] svg { display: none; }
[data-part="row.more"]::before { content: "View All"; font-size: 14px; line-height: 20px; font-weight: 500; color: #c084fc; }
[data-part="row.more"]:hover::before { text-decoration: underline; }
/* Row arrows (row.step), centred on the track. Latest Episodes: 40px black/80 rounds with a white/10
   hairline and shadow-lg, 16px outside the track, lucide chevrons, purple-600 on hover. Continue Watching:
   the same at the track edge, neutral-300, white on hover. Recently Added / Upcoming: black/60 at 80%
   opacity, no hairline, at the track edge, Font Awesome chevrons 10×16. */
[data-part="row.step"] { width: 40px !important; height: 40px !important; top: 50% !important; opacity: 1 !important; border: 1px solid rgba(255, 255, 255, 0.1) !important; background: rgba(0, 0, 0, 0.8) !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1) !important; color: #fff !important; }
[data-part="row.step"]:hover { background: #9333ea !important; }
[data-part="row.step"][data-dir="previous"] { left: 16px !important; }
[data-part="row.step"][data-dir="next"] { right: 16px !important; }
[data-slot="row"]:not([data-role="recent"]) [data-part="row.step"][data-dir="previous"] { left: 32px !important; }
[data-slot="row"]:not([data-role="recent"]) [data-part="row.step"][data-dir="next"] { right: 32px !important; }
[data-slot="row"][data-role="continue"] [data-part="row.step"] { color: #d4d4d4 !important; box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1) !important; }
[data-slot="row"][data-role="continue"] [data-part="row.step"]:hover { background: #fff !important; color: #000 !important; }
[data-slot="row"]:not([data-role="recent"]):not([data-role="continue"]) [data-part="row.step"] { border: 0 !important; box-shadow: none !important; background: rgba(0, 0, 0, 0.6) !important; opacity: 0.8 !important; }
[data-slot="row"]:not([data-role="recent"]):not([data-role="continue"]) [data-part="row.step"]:hover { background: rgba(0, 0, 0, 0.8) !important; opacity: 1 !important; }
[data-slot="row"]:not([data-role="recent"]):not([data-role="continue"]) [data-part="row.step"] svg { display: none; }
[data-slot="row"]:not([data-role="recent"]):not([data-role="continue"]) [data-part="row.step"]::before { content: ""; width: 10px; height: 16px; background: currentColor; -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20320%20512%27%3E%3Cpath%20d%3D%27M9.4%20233.4c-12.5%2012.5-12.5%2032.8%200%2045.3l192%20192c12.5%2012.5%2032.8%2012.5%2045.3%200s12.5-32.8%200-45.3L77.3%20256%20246.6%2086.6c12.5-12.5%2012.5-32.8%200-45.3s-32.8-12.5-45.3%200l-192%20192z%27%2F%3E%3C%2Fsvg%3E"); mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20320%20512%27%3E%3Cpath%20d%3D%27M9.4%20233.4c-12.5%2012.5-12.5%2032.8%200%2045.3l192%20192c12.5%2012.5%2032.8%2012.5%2045.3%200s12.5-32.8%200-45.3L77.3%20256%20246.6%2086.6c12.5-12.5%2012.5-32.8%200-45.3s-32.8-12.5-45.3%200l-192%20192z%27%2F%3E%3C%2Fsvg%3E"); -webkit-mask-size: contain; mask-size: contain; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; }
[data-slot="row"]:not([data-role="recent"]):not([data-role="continue"]) [data-part="row.step"][data-dir="next"]::before { transform: scaleX(-1); }
/* Latest Episodes (the recent row): white, tracking-tight, a 40px purple/10 tile with a 20px TV icon; VIEW ALL 10/900. */
[data-slot="row"][data-role="recent"] [data-part="row.title"] { color: #fff; letter-spacing: -0.75px; }
[data-slot="row"][data-role="recent"] [data-part="row.title"]::before { width: 40px; height: 40px; border-radius: 12px; background: rgba(168, 85, 247, 0.1); -webkit-mask-image: none; mask-image: none; }
[data-slot="row"][data-role="recent"] [data-part="row.title"]::after { content: ""; position: absolute; left: 10px; top: 50%; width: 20px; height: 20px; margin-top: -10px; background: #c084fc; -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27m17%202-5%205-5-5%27%2F%3E%3Crect%20width%3D%2720%27%20height%3D%2715%27%20x%3D%272%27%20y%3D%277%27%20rx%3D%272%27%2F%3E%3C%2Fsvg%3E"); mask-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27m17%202-5%205-5-5%27%2F%3E%3Crect%20width%3D%2720%27%20height%3D%2715%27%20x%3D%272%27%20y%3D%277%27%20rx%3D%272%27%2F%3E%3C%2Fsvg%3E"); -webkit-mask-size: contain; mask-size: contain; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; }
[data-slot="row"][data-role="recent"] [data-part="row.more"]::before { content: "View All"; padding: 0 12px; font-size: 10px; line-height: 15px; font-weight: 900; letter-spacing: 1px; text-transform: uppercase; color: #a3a3a3; }
